import{_ as t,b as a,c as i,g as r}from"./chunks/framework.86O3EbG5.js";const A=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"articles/artificial-intelligence/books/AI-modern-approach-homework/22.md","filePath":"articles/artificial-intelligence/books/AI-modern-approach-homework/22.md"}'),l={name:"articles/artificial-intelligence/books/AI-modern-approach-homework/22.md"};function d(h,e,p,n,o,_){return a(),i("div",null,[...e[0]||(e[0]=[r('<p>基于斯图尔特.罗素《人工智能：现代方法（第4版)）》的第 22 章&lt;强化学习&gt;，根据此章节的重点，并出一些从 基础→进阶→综合 的练习题，能让我将本章的知识串联起来</p><h2 id="一个mdp有状态a-b-动作left-right-折扣因子-γ-0-9。已知策略-π-在a执行left-在b执行right。转移与奖励" tabindex="-1">一个MDP有状态A,B，动作left,right，折扣因子 γ=0.9。已知策略 π：在A执行left，在B执行right。转移与奖励：</h2><p>A→left：0.8到A（奖励0），0.2到B（奖励1）。 B→right：1.0到A（奖励0）。 写出 V^π (A) 和 V^π (B) 的贝尔曼方程，并求解。</p><h2 id="td-0-更新-当前估计-v-a-0-5-v-b-0-8。智能体从a出发-采取动作后转移到b-收到奖励-r-2-γ-0-9-学习率-α-0-1。计算td误差和更新后的-v-a-。" tabindex="-1">TD(0)更新：当前估计 V(A)=0.5，V(B)=0.8。智能体从A出发，采取动作后转移到B，收到奖励 r=2，γ=0.9，学习率 α=0.1。计算TD误差和更新后的 V(A)。</h2><h2 id="q学习更新-当前-q-a-left-1-0-q-a-right-0-5。智能体在状态a执行left-转移到b-奖励-r-0-γ-0-9-在b处最大q值为-max-a-q-b-a-0-7-学习率-α-0-2。更新-q-a-left-。" tabindex="-1">Q学习更新：当前 Q(A,left)=1.0，Q(A,right)=0.5。智能体在状态A执行left，转移到B，奖励 r=0，γ=0.9，在B处最大Q值为 max_(a^&#39; ) Q(B,a^&#39;)=0.7，学习率 α=0.2。更新 Q(A,left)。</h2><h2 id="蒙特卡洛-mc-与td的比较-智能体在一个回合制任务中-经历了如下序列-状态-奖励" tabindex="-1">蒙特卡洛（MC）与TD的比较：智能体在一个回合制任务中，经历了如下序列（状态-奖励）：</h2><p>S_0 →┴⟡(1&amp;r=0) S_1 →┴⟡(1&amp;r=0) S_2 →┴⟡(1&amp;r=1) S_3 →┴⟡(1&amp;r=0) S_4（终止）。折扣因子 γ=1。 (1) 使用蒙特卡洛方法，计算每个状态 V(S_0),V(S_1),V(S_2),V(S_3)（使用首次访问MC）。 (2) 使用TD(0)方法，初始所有 V(s)=0，学习率 α=0.5，按顺序逐步更新，写出每一步后的V值。</p><h2 id="探索与利用-ε-greedy-一个老虎机-k臂赌博机-有3个动作-真实价值-q-1-0-5-q-2-0-2-q-3-0-3。当前估计-q-1-0-4-q-2-0-3-q-3-0-3。采用-ε-0-1-的ε-greedy策略。" tabindex="-1">探索与利用（ϵ-greedy）：一个老虎机（k臂赌博机）有3个动作，真实价值 q_1=0.5,q_2=0.2,q_3=0.3。当前估计 Q_1=0.4,Q_2=0.3,Q_3=0.3。采用 ϵ=0.1 的ϵ-greedy策略。</h2><p>(1) 在next step中，选择每个动作的概率分别是多少？ (2) 如果该步选择动作1，得到奖励1，更新 Q_1（学习率 α=0.1）。写出更新后的Q1。</p><h2 id="sarsa-vs-q学习-在一个确定性环境中-状态a可以执行动作left或right。当前q值-q-a-left-0-5-q-a-right-1-0-q-b-left-0-8-q-b-right-0-6。已知从a执行left到达b-奖励0-执行right到达终止-奖励10。γ-0-9-ε-0-贪心-。" tabindex="-1">SARSA vs Q学习：在一个确定性环境中，状态A可以执行动作left或right。当前Q值：Q(A,left)=0.5，Q(A,right)=1.0，Q(B,left)=0.8，Q(B,right)=0.6。已知从A执行left到达B，奖励0；执行right到达终止，奖励10。γ=0.9，ϵ=0（贪心）。</h2><p>(1) 如果在状态A，Q学习（off-policy）会选择哪个动作？并写出Q(A,left)的更新值。 (2) 如果是SARSA（on-policy），策略为贪心，选择哪个动作？写出Q(A,left)的更新值。两者有何不同？</p><h2 id="深度q网络-dqn-设计-你想用dqn训练一个玩atari游戏的智能体。" tabindex="-1">深度Q网络（DQN）设计：你想用DQN训练一个玩Atari游戏的智能体。</h2><p>(1) 描述DQN的两个关键技巧（经验回放、目标网络）的作用。 (2) 为什么直接使用非线性函数逼近（如神经网络）可能导致训练不稳定？ (3) 如果状态是游戏画面（像素），你会如何设计网络输入层和卷积层？ (4) 简述使用DQN时的训练循环步骤。</p><h2 id="策略梯度与reinforce" tabindex="-1">策略梯度与REINFORCE：</h2><p>(1) 写出策略梯度定理的表达式（目标函数梯度）。 (2) REINFORCE算法使用完整回报作为权重，它的局限性是什么？如何通过引入基线（baseline）减少方差？ (3) 与Q学习相比，策略梯度方法在处理连续动作空间时有何优势</p><h2 id="探索与利用平衡" tabindex="-1">探索与利用平衡：</h2><p>在一个医疗治疗推荐系统中，智能体需要学习给病人推荐最佳治疗方案（动作），目标是最大化长期健康回报（健康指标）。 (1) 为什么此问题适合用强化学习？ (2) 如果使用 ϵ ϵ-greedy探索，即随机尝试新方案，可能会给病人带来风险。你会提出什么替代的探索策略？ (3) 如何利用历史病历数据（离线数据）进行预训练，以减少在线探索的代价？ (4) 解释如何用离线策略评估（如优先经验回放）来利用历史数据。</p><h2 id="自动驾驶变道决策" tabindex="-1">自动驾驶变道决策：</h2><p>你设计一个自动驾驶汽车的变道决策系统。状态包括：当前车速、相邻车道前后车距离、本车位置等连续变量。动作：加速、减速、不变道、变道左、变道右。奖励函数：安全（无碰撞）、效率（速度）、舒适性（平顺）。 (1) 为什么这是一个连续状态空间问题？如何用强化学习解决？ (2) 你会选择值函数方法（如DQN）还是策略梯度方法（如PPO）？说明理由。 (3) 设计奖励函数时需要注意哪些问题？如何避免奖励稀疏导致学习困难？ (4) 在真实道路测试之前，如何在仿真环境中训练并评估策略的安全性？</p>',19)])])}const s=t(l,[["render",d]]);export{A as __pageData,s as default};
